package com.yumi.cafe.model;
import jakarta.persistence.*;import java.math.BigDecimal;
@Entity @Table(name="order_items") public class OrderItem { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) Order order; @Column(nullable=false) Long menuItemId; @Column(nullable=false) String itemName; @Column(nullable=false) String size; @Column(nullable=false) Integer quantity; @Column(nullable=false,precision=10,scale=2) BigDecimal unitPrice; @Column(nullable=false,precision=10,scale=2) BigDecimal lineTotal; public OrderItem(){} public void setOrder(Order o){order=o;}public void setMenuItemId(Long v){menuItemId=v;}public void setItemName(String v){itemName=v;}public void setSize(String v){size=v;}public void setQuantity(Integer v){quantity=v;}public void setUnitPrice(BigDecimal v){unitPrice=v;}public void setLineTotal(BigDecimal v){lineTotal=v;} public Long getMenuItemId(){return menuItemId;}public String getItemName(){return itemName;}public String getSize(){return size;}public Integer getQuantity(){return quantity;}public BigDecimal getUnitPrice(){return unitPrice;}public BigDecimal getLineTotal(){return lineTotal;}}
